// e2e/auth/login.spec.ts
import { test, expect } from '@playwright/test';
import { loginAs, testUsers } from '../fixtures/auth';

test.describe('Login Flow', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should login as admin and redirect to admin dashboard', async ({ page }) => {
    await loginAs(page, 'admin');

    await expect(page).toHaveURL('/admin/dashboard');
    await expect(page.locator('h1')).toContainText('Admin Dashboard');
    await expect(page.locator('[data-testid="user-menu"]')).toBeVisible();
  });

  test('should login as dosen and redirect to dosen dashboard', async ({ page }) => {
    await loginAs(page, 'dosen');

    await expect(page).toHaveURL('/dosen/dashboard');
    await expect(page.locator('h1')).toContainText('Dosen Dashboard');
  });

  test('should show error for invalid credentials', async ({ page }) => {
    await page.fill('[name="email"]', 'invalid@example.com');
    await page.fill('[name="password"]', 'wrongpassword');
    await page.click('button[type="submit"]');

    await expect(page.locator('[data-testid="error-message"]')).toBeVisible();
    await expect(page.locator('[data-testid="error-message"]')).toContainText('Invalid credentials');
    await expect(page).toHaveURL('/login');
  });

  test('should redirect to login when accessing protected routes unauthenticated', async ({ page }) => {
    await page.goto('/admin/dashboard');
    await expect(page).toHaveURL('/login');
  });
});
